#!/usr/bin/env python3
"""Current proposal renderer after lateral-column discomfort steering."""
import html,json
from study import ROOT,POP

def render():
    r=json.loads((ROOT/'lateral_results.json').read_text()); old=json.loads((ROOT/'results.json').read_text())
    n=r['nominal']; paths=r['posture_sensitivity']['vertical_1_anchor_2']; names=('baseline','previous','revised')
    css=(ROOT/'house-style.css').read_text(); lay=r['layouts']['revised']
    def grid(s):return '\n'.join(' '.join(s[i:i+5])+'   '+' '.join(s[i+5:i+10]) for i in range(0,30,10))
    def table(rows,labels=('v24','Previous','Revised')):
        return '<table style="width:100%;text-align:left"><thead><tr><th>Measure</th>'+''.join('<th>'+l+'</th>' for l in labels)+'</tr></thead><tbody>'+''.join('<tr><td>'+label+'</td>'+''.join(f'<td>{v:.3f}</td>' for v in values)+'</tr>' for label,values in rows)+'</tbody></table>'
    rows=[('Outer-edge tap load (%) ↓',[n[k]['outer_edge_tap_pct'] for k in names]),('Complete per-thumb path (u/character) ↓',[paths[k]['each_thumb_path_u_per_character'] for k in names]),('Immediate same-thumb travel (u/pair) ↓',[n[k]['same_thumb_travel_u_per_pair'] for k in names]),('Reach from assumed lower-center anchor (u/character) ↓',[n[k]['mean_anchor_reach_u'] for k in names]),('Long moves >3u per100 characters ↓',[paths[k]['long_moves_over_3u_per_100_chars'] for k in names]),('Space-adjacent travel (u/Space-adjacent pair) ↓',[paths[k]['space_adjacent_travel_u_per_pair'] for k in names]),('Right-thumb load including Space (%)',[n[k]['right_load_including_space_pct'] for k in names]),('Same-thumb adjacent pairs (%)',[n[k]['same_thumb_pct'] for k in names]),('Penalty-aware model score ↓',[n[k]['score_with_lateral_penalty'] for k in names])]
    penalty_rows=[(f'Penalty {p}',[r['penalty_sensitivity'][p][k]['score_with_lateral_penalty'] for k in names]) for p in ('0','0.5','1','2','4')]
    # Source-width geometry, schematic vertical pitch; no phone capture or measured pixels.
    cells=[]
    for ri,row in enumerate([list(lay[i:i+10]) for i in range(0,30,10)]+[['','','NUM','SYM','⇧','↵','␣','⌫','','']]):
        for ci,ch in enumerate(row):
            x=ci*9.4+(6 if ci>=5 else 0);tip=next((p for p,b in POP.items() if b==ch),'')
            label=html.escape(ch)+(f'<tspan x="{x+4.7}" dy="3.3" font-size="2.5">hold:{tip}</tspan>' if tip else '')
            cells.append(f'<rect x="{x+.2}" y="{ri*15+.2}" width="9" height="14.6" rx="1" fill="currentColor" opacity="{.04 if ci in (0,9) else .10}"/><text x="{x+4.7}" y="{ri*15+7}" text-anchor="middle" font-size="{3 if len(ch)>1 else 4.5}" fill="currentColor">{label}</text>')
    diagram='<svg role="img" aria-label="Revised Russian phone touch zones; outer screen-edge columns lower comfort" viewBox="0 0 100 60" style="width:100%;max-width:650px">'+''.join(cells)+'</svg>'
    source='https://github.com/shofel/pixel-tools/blob/9d64db0a5d27e4c5eb20e73820f2ea6dbc3b0d0a/boo-keyboard/'
    body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Russian phone thumbs — lower lateral-column use</title><style>{css}</style></head><body><main>
<header><p class="muted">2Thumbs · phone touchscreen · revised research only</p><h1>I lowered outer-column use; this revised candidate replaces the first proposal.</h1></header>
<section class="card pass"><strong>I incorporated lateral-column discomfort.</strong><p>The revised candidate uses the outer screen-edge columns for 3.11% of held-out letters and spaces, versus 7.87% in my first candidate and 6.45% in shipped v24. Complete modeled thumb travel is 13.5% below v24.</p></section>
<section class="card pending"><strong>I interpreted “lateral” as the two outside screen-edge columns.</strong><p>That means global columns0 and9, not the columns beside the center gap. This interpretation is explicit but unconfirmed. The discomfort is user-provided; the numerical penalty is an assumption. This is not a speed, accuracy or comfort claim, and I made no phone or application changes.</p></section>
<ol class="steps">
<li><h2>Keep the recovered phone geometry</h2><p>Two touch zones, each five columns × three alphabet rows plus footer. Each cell is9.4% of keyboard width; the full-height gap is6%, spanning47–53%. Left centers:4.7,14.1,23.5,32.9,42.3%; right:57.7,67.1,76.5,85.9,95.3%. These are source cell centers, not measured Android hit bounds, dp or millimeters. Vertical pitch remains a model assumption.</p><pre>Shipped v24:
{grid(r['layouts']['baseline'])}
· · NUM SYM ⇧   ↵ ␣ ⌫ · ·</pre><p>Sources pinned to the read-only inspected revision: <a href="{source}SPEC.html#L1">spec geometry/current controls</a>, <a href="{source}d_layout.py">unit/gap generator</a>, <a href="{source}russian_layout.py">Russian letters/popups</a>, <a href="{source}next_layout.py">footer/NUM generator</a>.</p><p class="see"><strong>You should see:</strong> a phone keyboard for two thumbs, not physical switches, stagger or eight-finger assignments.</p></li>
<li><h2>Move rare letters toward the uncomfortable edges</h2><p>Left thumb owns all left-half cells; right thumb owns all right-half cells, including Return, Space and Backspace. No other finger is assigned. Fainter edge-column shading means lower modeled comfort, <strong>not smaller targets</strong>.</p>{diagram}<pre>Revised:
{grid(lay)}
· · NUM SYM ⇧   ↵ ␣ ⌫ · ·</pre><p>The outside columns now hold ю/ф/ж and щ/ц/ш. All30 direct letters remain, plus е→ё, ь→ъ, ж→э popups attached to their moved parent letters; Shift supplies uppercase. No new gesture. All alphabet targets remain1u.</p><details><summary>Previous candidate — superseded, retained for comparison</summary><pre>{grid(r['layouts']['previous'])}</pre><p>This candidate did not explicitly penalize lateral-column discomfort. It is no longer the proposed layout.</p></details><p class="see"><strong>You should see:</strong> rare letters taking the uncomfortable edges, with controls and hit sizes unchanged.</p></li>
<li><h2>Compare all three on the same held-out public text</h2>{table(rows)}<p>One u is the horizontal cell pitch (9.4% of width). Complete path follows each thumb between its own taps even while the other thumb types; first positions reset per sentence. Immediate same-thumb travel only follows consecutive same-thumb character pairs. Relative to the previous candidate, revised edge use falls60.5%, while immediate same-thumb travel rises2.3% and nominal anchor reach rises0.7%. Complete thumb path improves another1.1%. This is the explicit comfort/travel tradeoff, not a claim that every metric improved.</p><p>All33 Russian letters are representable in every layout:100% of letter-plus-space test mass. Same-target pair rate1.25% and popup-letter rate0.492% are identical. Space contributes13.08% of characters;16,308 Space-adjacent pairs are included and Space stays in the same right footer cell. Same-thumb percentage is diagnostic, not a stand-alone objective or physical-key SFB metric.</p><p class="see"><strong>You should see:</strong> baseline, superseded candidate and revised candidate measured on identical text and denominators.</p></li>
<li><h2>Check how strongly the discomfort penalty matters</h2><p>I added <strong>2 abstract cost units per outer-edge tap</strong> to the previous model and ran one bounded train-only search. That value is not a measured thumb-pain or time coefficient. The following evaluates the same fixed layouts under several penalties; it does not independently re-optimize each penalty.</p>{table(penalty_rows)}<p>Without a lateral penalty, the previous candidate has the lower weighted score. At tested penalties0.5,1,2 and4 the revised candidate wins. The revised candidate therefore earns its recommendation through the added comfort preference, not by pretending the old objective was wrong.</p><p>Grip still matters. I checked vertical/horizontal pitch ratios0.7,1 and1.3 and lower-row anchors at center and one column either way. For the <em>previous</em> candidate, inner-shifted anchors at ratio0.7 made reach2.6% worse than v24; that earlier warning must not be mistaken for a measured new-phone result. All revised/previous/baseline posture results are in the <a href="lateral_results.json">saved sensitivity data</a>. No reach arc, phone size, hand size or actual posture was measured. Euclidean travel is a proxy; equal targets do not establish accuracy or Fitts-law time.</p><p class="see"><strong>You should see:</strong> a transparent penalty and posture sensitivity, not a fitted ergonomic guarantee.</p></li>
<li><h2>Preserve layer access and distinguish the draft</h2><p>Current v24 left NUM/SYM tap-toggle under200ms or hold/chord momentary. Right Return/Space ordinary taps stay ordinary; holds open SYM/NUM with native timeout and Space-swipe arbitration. Alphabet Shift stays. Right-side NUM is reachable while left NUM is held; left-side symbols while right Return is held. Same-side input may need a latched layer; one thumb cannot hold one cell and tap another simultaneously.</p><p>The unfinished draft discusses Dvorak apostrophe, double-space period, removing letter digit popups, NUM punctuation and QWERTY replacement; Shift movement/meaning is tentative. None is treated as implemented or decided here. Punctuation, Shift, layer-use frequency and actual popup travel/time are outside this Russian-letter-and-space comparison, not silently zero-cost experiences. Popup hold cost is the same abstract additive term for all three because incidence is identical.</p><p class="see"><strong>You should see:</strong> an alphabet research revision only; no new app, firmware or device behavior.</p></li>
<li><h2>Keep the next decision small</h2><p>The smallest useful check is whether the uncomfortable column really means the two outer screen edges modeled here. Until clarified, this is an assumption-labeled candidate, not permission to implement it. The existing owner context can resolve that without another repeated request. Learning cost is high and no global optimum or personal-corpus fit is claimed.</p><p class="see"><strong>You should see:</strong> the initial recommendation superseded, with no device-testing request or automatic rollout.</p><p class="decision">Reply when useful: outer edges is right / I meant a different column. No action is required now.</p></li></ol>
<details><summary>Evidence, reproduction, attribution and limits</summary><p>Public corpus: <a href="https://github.com/UniversalDependencies/UD_Russian-GSD/tree/r2.15">UD Russian-GSD r2.15</a>, wiki genre; contributors Ryan McDonald, Vitaly Nikolaev and Olga Lyashevskaya; <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA4.0</a>. Underlying text rights are distinct from Google annotations. See <a href="README.md">attribution and reproduction</a>. Derived frequency tables retain that license. No private prompt text is used or reported.</p><p>Preprocessing per sentence #text field: lowercase; retain all33 Russian letters including ё/ъ/э; collapse other character runs to one space; trim edges; aggregate unigrams and adjacent pairs without crossing sentence boundaries. Train only for search:3,849 sentences,409,519 letters+spaces,405,670 pairs. Held-out test:601 sentences,62,361 characters,61,760 pairs. Public bytes are SHA-256 bound in <a href="counts.json">counts/provenance</a>; test download digest is asserted again. This is not phone-use text or the historical corpus.</p><p>Base score = immediate same-thumb distance +0.25×anchor reach +0.35×same-thumb different-target rate +3×(right load−0.5)² +3×popup rate. Revised score adds2×outer-edge tap rate. Popup location is approximated at its parent center; actual popup movement unknown. Baseline and previous model results, including H=1/3/6 abstract hold penalties, remain in <a href="results.json">initial results</a>. Equal popup incidence makes hold penalty a common offset, not validated latency. Lower-center anchors and no cross-gap typing are assumed. Target acquisition, errors, screen obstruction, grip biomechanics and language familiarity are not modeled.</p><p>Original search and revised search each use3 restarts×12,000 swaps; revised seed20261103. Search is bounded, not exhaustive. Whole-thumb paths are supplementary held-out evaluation rather than the optimized objective. <a href="lateral_study.py">Revised model/search</a>, <a href="lateral_results.json">all revised metrics/sensitivities</a>, <a href="test_study.py">offline checks</a>, <a href="render_lateral_report.py">renderer</a>. Reproduction commands are in the README; coordinate resources and check memory first. Available memory was13GiB; bounded runs used nice15.</p><p>All changes are under this documentation directory. No Android/firmware source edits, phone input/gestures/screenshots, installation, flashing or deployment. Historical independent Cantor work remains separate and read-only. Browser preview of local files is blocked by the supported browser; no server was started to work around it. The report is a static schematic, not a screenshot or experience certification.</p></details><footer>I will publish the research only. I will not change the keyboard or touch the phone without a separate implementation order.</footer></main></body></html>'''
    (ROOT/'proposal.html').write_text(body)
    print(ROOT/'proposal.html')
if __name__=='__main__':render()
